import{H as e,V as t,et as n,j as r}from"./chunks/framework.ByEJxCeM.js";import"./chunks/assets.B5FjAcX4.js";var i=JSON.parse(`{"title":"问题分析","description":"","frontmatter":{},"headers":[],"relativePath":"java/transaction-management/problem-analysis.md","filePath":"java/transaction-management/problem-analysis.md"}`),a={name:`java/transaction-management/problem-analysis.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="问题分析" tabindex="-1">问题分析 <a class="header-anchor" href="#问题分析" aria-label="Permalink to “问题分析”">​</a></h1><p>实现新增员工功能中，要操作两次数据库，新增员工的同时要新增其工作经历，需要执行了两次 insert 操作。</p><ul><li><p>第一次：保存员工的基本信息到 <code>emp</code> 表中。</p></li><li><p>第二次：保存员工的工作经历信息到 <code>emp_expr</code> 表中。</p></li></ul><p>如果说，保存员工的基本信息成功了，而保存员工的工作经历信息出错了，会发生什么现象呢？那接下来，我们来做一个测试 。 我们可以在代码中，人为在保存员工的service层的save方法中，构造一个错误：</p><p><img src="/blog-notes/assets/image-48.gXk_yuqX.png" alt="image.png" width="1292" height="641"></p><p>那接下来，我们就重启服务，打开浏览器，来做一个测试：</p><p><img src="/blog-notes/assets/image-54.DULlfV8A.png" alt="image.png" width="1895" height="919"></p><p>点击 “保存” 之后，提示 “系统接口异常”。我们可以打开IDEA控制台看一下，报出的错误信息。 我们看到，保存了员工的基本信息之后，系统出现了异常。</p><p><img src="/blog-notes/assets/image-1.SEynhZIC.png" alt="image.png" width="1838" height="704"></p><p>我们再打开数据库，看看表结构中的数据是否正常。</p><p>1). <code>emp</code> 员工表中是有 <code>shaseng</code> 这条数据的。</p><p><img src="/blog-notes/assets/image-37.BwQpzzP7.png" alt="image.png" width="1511" height="685"></p><p>2). <code>emp_expr</code> 表中没有该员工的工作经历信息。</p><p><img src="/blog-notes/assets/image-27.BWY8_VzH.png" alt="image.png" width="1512" height="236"></p><p>最终，我们看到，程序出现了异常 ，员工表 <code>emp</code> 数据保存成功了, 但是 <code>emp_expr</code> 员工工作经历信息表，数据保存失败了。 那是否允许这种情况发生呢？</p><ul><li><p>不允许</p></li><li><p>因为这属于一个业务操作，如果保存员工信息成功了，保存工作经历信息失败了，就会造成数据库数据的不完整、不一致。</p></li></ul><p>那如何解决这个问题呢？ 这需要通过数据库中的<strong>事务</strong>来解决这个问题。</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};